from pathlib import Path
import json,hashlib,re
O=Path('analysis/activity-push-2026-10-21/triggers'); R=Path('analysis/native_decode/decoded')
def ev(path,term):
 p=R/path;s=p.read_text();n=next(i+1 for i,l in enumerate(s.splitlines()) if term in l)
 return {'source':path,'line':n,'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'symbol':term}
